// Offline diagnostic. Mirrors the already-shipped native Finger brightness
// fixture's strings, notes, velocities and 40x256 settling schedule.
#include "DSP/AcustraEngine.h"
#include <array>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <memory>
#include <stdexcept>
#include <string>
#include <vector>
#include <cstring>
#include <cstddef>
#include <sstream>
#include <cmath>

namespace acustra {
struct AcustraEngineTestAccess {
 static std::string reseed(AcustraEngine& e,int channel,std::uint32_t seed) {
  auto& v=e.voices_[static_cast<std::size_t>(channel-1)];
  if(!v.played || !v.attackFired || !(v.excitationEnvelope>0))throw std::runtime_error("expected fired pluck with live burst");
  if(v.contactNoiseSamples!=0 || v.contactNoiseString!=0 || v.contactNoiseClick!=0)throw std::runtime_error("contact noise must already be zero");
  const auto before=v.excitationNoiseState,pluck=v.randomState;
  const float envelope=v.excitationEnvelope;
  std::vector<unsigned char> expected(sizeof(v));std::memcpy(expected.data(),&v,sizeof(v));
  if(seed!=0) {
   const std::ptrdiff_t offset=reinterpret_cast<unsigned char*>(&v.excitationNoiseState)-reinterpret_cast<unsigned char*>(&v);
   std::memcpy(expected.data()+offset,&seed,sizeof(seed));v.excitationNoiseState=seed;
  }
  if(std::memcmp(expected.data(),&v,sizeof(v))!=0 || v.randomState!=pluck || v.excitationEnvelope!=envelope)throw std::runtime_error("seed edit changed other voice state");
  std::ostringstream s;s<<std::setprecision(17)<<"{\"single_field_guard\":true,\"burst_rng_before\":"<<before<<",\"burst_rng_after\":"<<v.excitationNoiseState
   <<",\"pluck_rng\":"<<pluck<<",\"excitation_envelope\":"<<envelope<<",\"contact_noise_samples\":"<<v.contactNoiseSamples
   <<",\"contact_noise_string\":"<<v.contactNoiseString<<",\"contact_noise_click\":"<<v.contactNoiseClick<<"}";return s.str();
 }
};
}

int main(int argc,char** argv) {
 if(argc!=4)return 2;
 const auto seed=static_cast<std::uint32_t>(std::stoul(argv[1]));
 const double seconds=std::stod(argv[2]);
 if(seconds!=0.4 && seconds!=1.4)return 2;
 const std::filesystem::path out(argv[3]); std::filesystem::create_directories(out);
 constexpr std::array<std::array<int,2>,8> notes {{{40,1},{45,2},{51,3},{57,4},{60,5},{66,6},{72,6},{78,6}}};
 std::ofstream manifest(out/"manifest.json"); manifest << "{\"probe\":\"Existing Finger velocity fixture extended to both declared models and rates\",\"examples\":[";
 bool first=true;
 for(int model=0;model<2;++model) for(int rate:{44100,48000,96000}) for(auto note:notes) for(int velocity:{16,112}) {
  acustra::EngineParameters p; p.picking=acustra::PickingTechnique::Finger;p.room=0.0f;
  if(model==1) {p.guitarModel=acustra::GuitarModel::Bellido1978;p.shape=acustra::BodyShape::Auditorium;p.bodyMaterial=acustra::BodyMaterial::Mahogany;}
  else {p.guitarModel=acustra::GuitarModel::Original;p.shape=acustra::BodyShape::Dreadnought;p.bodyMaterial=acustra::BodyMaterial::Spruce;}
  auto e=std::make_unique<acustra::AcustraEngine>();e->prepare(rate,256);e->setParameters(p);e->setStringPerChannelMode(true);
  std::array<float,256> l{},r{};for(int i=0;i<40;++i)e->process(l.data(),r.data(),256);
  e->noteOn(note[0],static_cast<float>(velocity)/127.0f,note[1]);
  const auto guard=acustra::AcustraEngineTestAccess::reseed(*e,note[1],seed);
  const std::string modelName=model==0?"original":"bellido1978";
  const std::string key=modelName+"-r"+std::to_string(rate)+"-m"+std::to_string(note[0])+"-v"+std::to_string(velocity);
  std::ofstream guardFile(out/(key+".guard.json"));guardFile<<guard<<"\n";if(!guardFile)throw std::runtime_error("guard write failed");
  std::ofstream audio(out/(key+".f32"),std::ios::binary);const int count=static_cast<int>(seconds*rate);
  for(int offset=0;offset<count;offset+=256) {const int n=std::min(256,count-offset);e->process(l.data(),r.data(),n);for(int i=0;i<n;++i){if(!std::isfinite(l[i]) || !std::isfinite(r[i]))throw std::runtime_error("nonfinite output");audio.write(reinterpret_cast<const char*>(&l[i]),sizeof(float));audio.write(reinterpret_cast<const char*>(&r[i]),sizeof(float));}}
  if(!audio) throw std::runtime_error("audio write failed");
  if(!first)manifest<<',';first=false;
  manifest<<"{\"id\":\""<<key<<"\",\"model\":\""<<modelName<<"\",\"sample_rate\":"<<rate<<",\"midi\":"<<note[0]<<",\"velocity\":"<<velocity<<",\"string_channel\":"<<note[1]<<",\"channels\":2,\"path\":\""<<key<<".f32\"}";
 }
 manifest<<"]}\n"; if(!manifest)throw std::runtime_error("manifest write failed");
 std::cout<<"Wrote 96 both-model native Finger probes.\n";
}

