friend=r'''
namespace acustra {
struct AcustraEngineTestAccess {
 static std::array<float,3> gains(const AcustraEngine& e,int channel,bool tail=false) {
  const auto& v=e.voices_[static_cast<std::size_t>(channel-1)];
#if ACUSTRA_FINGER_BURST_DIRECTION_SCREEN
  return tail ? std::array<float,3>{v.tailExcitationNormal,v.tailExcitationParallel,v.tailExcitationFingerProjection?1.0f:0.0f}
              : std::array<float,3>{v.excitationNormal,v.excitationParallel,v.excitationFingerProjection?1.0f:0.0f};
