import numpy as np
HERE=Path(__file__).resolve().parent
sys.path.insert(0,str(HERE/'source/Tools'))
import FitPhysicalModel as F
p=argparse.ArgumentParser();p.add_argument('directory',type=Path);p.add_argument('output',type=Path);p.add_argument('--baseline',type=Path);a=p.parse_args()
sha=lambda path:hashlib.sha256(path.read_bytes()).hexdigest()
def clean(x):
 if isinstance(x,dict):return {str(k):clean(v) for k,v in x.items()}
 if isinstance(x,(tuple,list)):return [clean(v) for v in x]
 if isinstance(x,(bool,np.bool_)):return bool(x)
 if isinstance(x,(float,np.floating)):return float(x) if math.isfinite(x) else None
 if isinstance(x,(int,np.integer)):return int(x)
 return x
def stroke_onset(x,rate):
 # Same trailing1ms RMS,10% discovery,walkback to1% as existing native fixture.
 width=round(rate*.001);energy=x*x;prefix=np.r_[0,np.cumsum(energy)];s=np.arange(x.size);sums=prefix[1:]-prefix[np.maximum(s+1-width,0)];rms=np.sqrt(np.maximum(sums,0)/width);largest=rms.max();found=np.flatnonzero(rms>.1*largest)
 if not found.size:return 0
 onset=int(found[0]);
 while onset>0 and rms[onset]>.01*largest:onset-=1
 return onset
def balance(x,rate,midi,onset):
 begin=onset+round(.03*rate);count=round(.3*rate);segment=x[begin:begin+count];power=np.abs(np.fft.rfft(segment*np.hanning(segment.size),1<<16))**2;frequencies=np.fft.rfftfreq(1<<16,1/rate);f0=440*2**((midi-69)/12);peaks=[]
 for h in range(1,13):
  f=h*f0;selected=(frequencies>=f*.975)&(frequencies<=f*1.025+2);peaks.append(float(power[selected].max()) if np.any(selected) else 0)
 return 10*np.log10(max(sum(peaks[4:]),1e-30)/max(sum(peaks[:4]),1e-30))
def measure(directory):
 manifest=json.loads((directory/'manifest.json').read_text());rows={}
 for e in manifest['examples']:
  path=directory/e['path'];rate,x=F._read_audio(e,directory,None,None);stereo=np.fromfile(path,dtype='<f4').reshape(-1,2);nz=np.flatnonzero(np.any(stereo!=0,axis=1));stroke=stroke_onset(x,rate);onset=F._onset(x,rate)
  levels,tuning,settled,sl=F._harmonic_features(x,rate,onset,e['midi']);early=F._pitch_trajectory_features(x,rate,onset,settled,sl)
  rows[e['id']]={**e,'sha256':sha(path),'first_nonzero_sample':int(nz[0]) if nz.size else None,'stroke_onset_sample':stroke,'fit_onset_sample':onset,'velocity_balance_db':balance(x,rate,e['midi'],stroke),'settled_pitch_cents_median_H1_H4':np.nanmedian(tuning[:4]),'H1_pitch_cents':tuning[0],'early_relative_pitch_cents':early.tolist()}
 return rows
rows=measure(a.directory);base=measure(a.baseline) if a.baseline else rows
cells=[]
for model in ['original','bellido1978']:
 for rate in [44100,48000,96000]:
  rises=[]
  for midi in [40,45,51,57,60,66,72,78]:
   q=[r for r in rows.values() if r['model']==model and r['sample_rate']==rate and r['midi']==midi];by_v={r['velocity']:r for r in q};rises.append({'midi':midi,'rise_db':by_v[112]['velocity_balance_db']-by_v[16]['velocity_balance_db']})
  median=np.median([r['rise_db'] for r in rises]);cells.append({'model':model,'sample_rate':rate,'median_rise_db':median,'gate8_to10_db':bool(8<=median<=10),'notes':rises})
comparisons=[]
for key,r in rows.items():
 b=base[key];pitch=r['settled_pitch_cents_median_H1_H4']-b['settled_pitch_cents_median_H1_H4'];early=np.asarray(r['early_relative_pitch_cents'])-b['early_relative_pitch_cents'];first=r['first_nonzero_sample']==b['first_nonzero_sample'];onset=1000*(r['fit_onset_sample']-b['fit_onset_sample'])/r['sample_rate'];finite=early[np.isfinite(early)]
 comparisons.append({'id':key,'first_nonzero_unchanged':first,'fit_onset_delta_ms':onset,'settled_pitch_delta_cents':pitch,'early_pitch_delta_cents':early.tolist(),'onset_gate':first and abs(onset)<=1,'pitch_gate':bool(np.isfinite(pitch) and abs(pitch)<=3 and len(finite)==3 and np.max(np.abs(finite))<=3)})
report={'protocol':{'source':'Native probe mirrors existing AcustraEngineTests.cpp Finger velocity fixture notes/strings/velocities and40x256 quiet settling blocks; actual both-model presets extended to44.1/48/96k','brightness':'Existing test energy-balance definition:strongest line within-2.5%..+2.5%+2Hz of each nominalH1-H12;Hann spectrum30–330ms after trailing1ms RMS stroke onset;10log10(sumH5-H12/sumH1-H4);FFT65536','pitch':'Frozen FitPhysicalModel measured partial trajectory;median settled tuningH1-H4 against MIDI plus early shift relative to each settled partial;raw H1 also reported','onset':'Exact first nonzero stereo sample plus frozen FitPhysicalModel1ms own-signal onset;maximum1ms descriptor change allowed'},'script_sha256':sha(Path(__file__)),'rows':list(rows.values()),'velocity_cells':cells,'comparisons':comparisons,'gates':{'velocity_rise':all(r['gate8_to10_db'] for r in cells),'onset':all(r['onset_gate'] for r in comparisons),'pitch':all(r['pitch_gate'] for r in comparisons)}}
a.output.write_text(json.dumps(clean(report),indent=2,allow_nan=False)+'\n')
for r in cells:print(r['model'],r['sample_rate'],'median rise',round(float(r['median_rise_db']),4),'gate',r['gate8_to10_db'])
