  value={'attack_share_db':attack,'attack_onset_sample':onset,'attack_onset_ms':1000*onset/rate,'balance_db':A.harmonic_balance_db(sig,rate,midi)}
  if args.decay:
   fundamental=440*2**((midi-69)/12)
   first=dict(D.partial_rates(sig,rate,fundamental,window=8192));check=dict(D.partial_rates(sig,rate,fundamental,window=4096))
   value['partial_admission']={'8192':len(first),'4096':len(check),'common_stable':sum(f in check and abs(v-check[f])<=3 for f,v in first.items())}
   value['stable_partial_rates']={f:v for f,v in first.items() if f in check and abs(v-check[f])<=3}
  cache[key]=value;source_inputs[str(path)]={'sha256':sha(path),'sample_rate':rate,'channels':entry['channels']}
 return cache[key]
report={'protocol':{'scope':'Cross-instrument transfer with actual declared Original Dreadnought/Spruce and Bellido Auditorium/Mahogany presets; not matching either source guitar exactly','attack':'Own1ms RMS-energy follower crossing0.0025 of first250ms peak, then0–15ms periodic Hann window with4x zero padding;2–12kHz power divided by80–12kHz total; paired median model-minus-target, not difference of medians','harmonic_balance':'Own2%-of-whole-record-peak sample onset;80–250ms symmetric Hann,4x zero padding;mean peak dB H5–H12 minus mean peak dB H1–H4,35cent search; paired median; no explicit interharmonic-noise floor in this diagnostic','decay':'AuditDampingCurve own2%-peak onset;STFT8192 Hann,7/8 overlap and4096 check;H1–H40 <=9kHz;0.15–1.2sec,12x interharmonic-power-floor and within45dB ownpeak,>=10frames;decaying slope>1dB/s;306/602/668Hz+-50cent artefact mask;admit only when each side agrees within3dB/s across windows;then pair exact nominal partial frequencies','limitations':['Monophonic captures; microphone/room and unknown source fingering can affect apparent shape and decay.','Martin technique unknown and remains Finger primary by prior policy; no style selected by score.','Nominal-partial peak slope can mix polarization doublets; it is not an identified intrinsic string-loss coefficient.','Harmonic balance lacks independent noise-floor admission and can be affected by notches/weak partials; cannot by itself authorize a parameter.','Admission can change with width; report coverage and all rows.','All files measured in mono average; native stereo capture is preserved on disk; gain cancels from shape but dynamics stays scored separately.']},'scripts':{str(p.relative_to(HERE)):sha(p) for p in [Path(__file__),HERE/'source/Tools/FitPhysicalModel.py',HERE/'source/Tools/AuditAttackBands.py',HERE/'source/Tools/AuditDampingCurve.py']},'render_root':str(args.renders.resolve()),'models':{},'inputs':source_inputs}
bands=[(80,120),(120,180),(180,270),(270,400),(400,600),(600,900),(900,1350),(1350,2000),(2000,3000),(3000,4500),(4500,6800),(6800,9000)]
for model in ['original','bellido1978']:
 result={}
 specs=[('bank_train','bank-'+model,'train.json'),('bank_validation','bank-'+model,'validation.json'),('bank_flattop','bank-'+model,'flattop.json'),('eastman_pick','external-'+model,'eastman.flattop-pick.json'),('eastman_finger_all','external-'+model,'eastman.flattop-finger-all.json'),('martin_primary_finger','external-'+model,'martin-hd28.martin-hd28.json')]
 for name,directory,filename in specs:
  path=args.renders/directory/filename;manifest=json.loads(path.read_text());rows=[];paired=[]
