// Frozen offline capture check: actual public same-string repeated attack.
#include "DSP/AcustraEngine.h"
#include <array>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <memory>
#include <stdexcept>
namespace acustra {
struct AcustraEngineTestAccess {
 static std::array<float,3> projection(const AcustraEngine& e,bool tail=false) {
  const auto& v=e.voices_[0];
#if ACUSTRA_FINGER_BURST_DIRECTION_SCREEN
  return tail ? std::array<float,3>{v.tailExcitationNormal,v.tailExcitationParallel,v.tailExcitationFingerProjection?1.0f:0.0f}
              : std::array<float,3>{v.excitationNormal,v.excitationParallel,v.excitationFingerProjection?1.0f:0.0f};
#else
  (void)v;(void)tail;return {0.76f,0.51f,0.0f};
#endif
 }
 static bool validCapture(const AcustraEngine& e) {
  const auto& v=e.voices_[0];return v.played&&v.attackFired&&v.tailActive&&v.tailContactTravel.active;
 }
};
}
int main() {
 std::cout<<std::setprecision(17)<<"{\"scope\":\"Six actual same-string repeated attacks; captured projection identity plus finite native output only. Not a complete capture-energy/passivity or listener proof.\",\"cases\":[";bool first=true;
 for(int model=0;model<2;++model)for(int rate:{44100,48000,96000}) {
  acustra::EngineParameters p;p.picking=acustra::PickingTechnique::Finger;p.room=0;
  if(model==1){p.guitarModel=acustra::GuitarModel::Bellido1978;p.shape=acustra::BodyShape::Auditorium;p.bodyMaterial=acustra::BodyMaterial::Mahogany;}
  auto e=std::make_unique<acustra::AcustraEngine>();e->prepare(rate,256);e->setParameters(p);e->setStringPerChannelMode(true);
  std::array<float,256> l{},r{};for(int b=0;b<40;++b)e->process(l.data(),r.data(),256);
  e->noteOn(40,112.0f/127.0f,1);e->process(l.data(),r.data(),64);
  const auto old=acustra::AcustraEngineTestAccess::projection(*e);e->noteOn(40,16.0f/127.0f,1);
  const auto captured=acustra::AcustraEngineTestAccess::projection(*e,true);const auto current=acustra::AcustraEngineTestAccess::projection(*e);
  if(old!=captured||!acustra::AcustraEngineTestAccess::validCapture(*e))throw std::runtime_error("old in-flight contact projection was not captured exactly");
#if ACUSTRA_FINGER_BURST_DIRECTION_SCREEN
  if(old==current)throw std::runtime_error("capture exercise was vacuous: new projection did not differ");
#endif
  double peak=0;for(int b=0;b<24;++b){e->process(l.data(),r.data(),256);for(int s=0;s<256;++s){if(!std::isfinite(l[s])||!std::isfinite(r[s]))throw std::runtime_error("nonfinite repeated attack");peak=std::max(peak,std::max(std::abs(static_cast<double>(l[s])),std::abs(static_cast<double>(r[s]))));}}
  if(!first)std::cout<<',';first=false;std::cout<<"{\"model\":\""<<(model==0?"original":"bellido1978")<<"\",\"rate\":"<<rate<<",\"old_normal\":"<<old[0]<<",\"old_parallel\":"<<old[1]<<",\"captured_normal\":"<<captured[0]<<",\"captured_parallel\":"<<captured[1]<<",\"new_normal\":"<<current[0]<<",\"new_parallel\":"<<current[1]<<",\"old_differs_from_new\":"<<(old!=current?"true":"false")<<",\"capture_exact\":true,\"finite\":true,\"peak\":"<<peak<<"}";
 }
 std::cout<<"]}\n";
}

