namespace acustra {
struct AcustraEngineTestAccess {
 static std::array<float,3> gains(const AcustraEngine& e,int channel,bool tail=false) {
  const auto& v=e.voices_[static_cast<std::size_t>(channel-1)];
#if ACUSTRA_FINGER_BURST_DIRECTION_SCREEN
  return tail ? std::array<float,3>{v.tailExcitationNormal,v.tailExcitationParallel,v.tailExcitationFingerProjection?1.0f:0.0f}
              : std::array<float,3>{v.excitationNormal,v.excitationParallel,v.excitationFingerProjection?1.0f:0.0f};
#else
  (void)v;(void)tail;return {0.76f,0.51f,0.0f};
#endif
 }
 static std::string source(const AcustraEngine& e,int channel) {
  const auto& v=e.voices_[static_cast<std::size_t>(channel-1)];auto g=gains(e,channel);
  const double total=static_cast<double>(g[0])*g[0]+static_cast<double>(g[1])*g[1];
  constexpr double legacy=static_cast<double>(0.76f)*0.76f+static_cast<double>(0.51f)*0.51f;
  const double normError=total-legacy;const double directionError=total>0?static_cast<double>(g[0])*g[0]/total-v.polarisationMix:1;
  if(std::abs(normError)>4*std::numeric_limits<float>::epsilon()*legacy || (g[2]>0 && std::abs(directionError)>4*std::numeric_limits<float>::epsilon()))throw std::runtime_error("actual stored projection norm/direction guard failed");
  std::uint64_t hash=14695981039346656037ULL;
  for(const auto& loop:v.loops)for(float value:loop.delay) {
   if(!std::isfinite(value))throw std::runtime_error("nonfinite initial wave");
   const auto* bytes=reinterpret_cast<const unsigned char*>(&value);
   for(std::size_t i=0;i<sizeof(value);++i){hash^=bytes[i];hash*=1099511628211ULL;}
  }
  std::ostringstream s;s<<std::setprecision(17)<<"{\"normal_gain\":"<<g[0]<<",\"parallel_gain\":"<<g[1]<<",\"rotated_finger\":"<<(g[2]>0?"true":"false")<<",\"source_vector_norm_sq\":"<<total<<",\"legacy_vector_norm_sq\":"<<legacy<<",\"norm_error\":"<<normError<<",\"direction_error\":"<<directionError
   <<",\"polarisation_mix\":"<<v.polarisationMix<<",\"initial_delay_histories_fnv1a64\":\""<<hash<<"\",\"excitation_envelope\":"<<v.excitationEnvelope<<",\"excitation_decay\":"<<v.excitationDecay<<",\"excitation_colour\":"<<v.excitationColour<<",\"excitation_soft\":"<<(v.excitationSoft?"true":"false")<<",\"excitation_white\":"<<(v.excitationWhite?"true":"false")<<",\"pluck_rng\":"<<v.randomState<<",\"burst_rng\":"<<v.excitationNoiseState<<",\"contact_samples\":"<<v.contactNoiseSamples<<",\"contact_string\":"<<v.contactNoiseString<<",\"contact_click\":"<<v.contactNoiseClick<<",\"attack_slope_energy\":"<<v.attackSlopeEnergy<<",\"attack_pitch_cents\":"<<v.attackPitchCents<<",\"slip_pole\":"<<v.releaseSlipPole<<",\"reference_pole\":"<<v.releaseReferencePole<<",\"pluck_point\":"<<v.pluckPoint<<",\"contact_period\":"<<v.contactPeriodSamples<<",\"loop0_delay\":"<<v.loops[0].currentDelay<<",\"loop1_delay\":"<<v.loops[1].currentDelay<<",\"contact_travel_enabled\":"<<(v.contactTravelEnabled?"true":"false")<<",\"attack_fired\":"<<(v.attackFired?"true":"false")<<"}";return s.str();
 }
 static bool tailActive(const AcustraEngine& e,int channel) {const auto& v=e.voices_[static_cast<std::size_t>(channel-1)];return v.tailActive && v.tailContactTravel.active;}
};
}

int main(int argc,char** argv) {
 if(argc!=2 && argc!=3) return 2;
 const bool thumb=argc==3 && std::string(argv[2])=="thumb";
 if(argc==3 && !thumb)return 2;
 const std::filesystem::path out(argv[1]); std::filesystem::create_directories(out);
 constexpr std::array<std::array<int,2>,8> notes {{{40,1},{45,2},{51,3},{57,4},{60,5},{66,6},{72,6},{78,6}}};
 std::ofstream manifest(out/"manifest.json"); manifest << "{\"probe\":\"Existing Finger velocity fixture extended to both declared models and rates\",\"examples\":[";
 bool first=true;
 for(int model=0;model<2;++model) for(int rate:{44100,48000,96000}) for(auto note:notes) for(int velocity:{16,112}) {
  acustra::EngineParameters p; p.picking=thumb?acustra::PickingTechnique::Thumb:acustra::PickingTechnique::Finger;p.room=0.0f;
  if(model==1) {p.guitarModel=acustra::GuitarModel::Bellido1978;p.shape=acustra::BodyShape::Auditorium;p.bodyMaterial=acustra::BodyMaterial::Mahogany;}
  else {p.guitarModel=acustra::GuitarModel::Original;p.shape=acustra::BodyShape::Dreadnought;p.bodyMaterial=acustra::BodyMaterial::Spruce;}
  auto e=std::make_unique<acustra::AcustraEngine>();e->prepare(rate,256);e->setParameters(p);e->setStringPerChannelMode(true);
  std::array<float,256> l{},r{};for(int i=0;i<40;++i)e->process(l.data(),r.data(),256);
  e->noteOn(note[0],static_cast<float>(velocity)/127.0f,note[1]);
  const std::string modelName=model==0?"original":"bellido1978";
  const std::string key=modelName+"-r"+std::to_string(rate)+"-m"+std::to_string(note[0])+"-v"+std::to_string(velocity);
  std::ofstream guard(out/(key+".source.json"));guard<<acustra::AcustraEngineTestAccess::source(*e,note[1])<<"\n";if(!guard)throw std::runtime_error("source guard write failed");
  std::ofstream audio(out/(key+".f32"),std::ios::binary);const int count=static_cast<int>(1.4*rate);
  for(int offset=0;offset<count;offset+=256) {const int n=std::min(256,count-offset);e->process(l.data(),r.data(),n);for(int i=0;i<n;++i){if(!std::isfinite(l[i])||!std::isfinite(r[i]))throw std::runtime_error("nonfinite output");audio.write(reinterpret_cast<const char*>(&l[i]),sizeof(float));audio.write(reinterpret_cast<const char*>(&r[i]),sizeof(float));}}
  if(!audio) throw std::runtime_error("audio write failed");
  if(!first)manifest<<',';first=false;
  manifest<<"{\"id\":\""<<key<<"\",\"model\":\""<<modelName<<"\",\"sample_rate\":"<<rate<<",\"midi\":"<<note[0]<<",\"velocity\":"<<velocity<<",\"string_channel\":"<<note[1]<<",\"channels\":2,\"path\":\""<<key<<".f32\"}";
 }
 manifest<<"]}\n"; if(!manifest)throw std::runtime_error("manifest write failed");
 std::cout<<"Wrote 96 both-model native Finger probes.\n";
}

