// Ignored offline source geometry/native observer diagnostic. No engine edits.
#include "DSP/AcustraEngine.h"
#include <algorithm>
#include <array>
#include <bit>
#include <cmath>
#include <complex>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <memory>
#include <numbers>
#include <stdexcept>
#include <string>
#include <vector>

namespace acustra {
struct AcustraEngineTestAccess {
    static bool ports(const AcustraEngine& e) {
        return e.bridgeCouplingEnabled_ && e.sympatheticStringsEnabled_
            && std::all_of(e.voices_.begin(),e.voices_.end(),[](const auto& v) {
                return std::isfinite(v.characteristicImpedance) && v.characteristicImpedance>0.0f;
            });
    }
    static std::vector<double> coefficients(const AcustraEngine& e) {
        std::vector<double> result{double(e.bodyBank_.count),double(e.bodyBank_.ordered),double(e.bridgeLoad_.activeModeCount),
            e.bridgeLoad_.immediateHeave,e.bridgeLoad_.immediateCross,e.bridgeLoad_.immediateRock};
        const auto& b=e.bodyBank_;
        for(int i=0;i<b.count;++i) {
            if(!(std::hypot(b.poleReal[i],b.poleImaginary[i])<1.0f))
                throw std::runtime_error("unstable/nonfinite body pole");
            for(float x:{b.poleReal[i],b.poleImaginary[i],b.leftReal[i],b.leftImaginary[i],
                b.rightReal[i],b.rightImaginary[i],b.leftMomentReal[i],b.leftMomentImaginary[i],
                b.rightMomentReal[i],b.rightMomentImaginary[i]}) result.push_back(x);
        }
        const auto& bridge=e.bridgeLoad_;
        for(int k=0;k<bridge.activeModeCount;++k) {
            const int i=bridge.activeModes[k];result.push_back(i);result.push_back(bridge.rocking[i]?1.0:0.0);
            for(const auto* m:{&bridge.heaveModes[i],&bridge.rockModes[i]}) {
                const auto root=(-m->denominator1+std::sqrt(std::complex<double>(m->denominator1*m->denominator1-4*m->denominator2,0)))/2.0;
                if(!(std::abs(root)<1.0)) throw std::runtime_error("unstable/nonfinite bridge pole");
                for(double x:{m->denominator1,m->denominator2,m->numerator1,m->numerator2})result.push_back(x);
            }
            for(float x:{bridge.residueHeave[i],bridge.residueCross[i],bridge.residueRock[i]})result.push_back(x);
        }
        for(double x:result) if(!std::isfinite(x)) throw std::runtime_error("nonfinite modal coefficient");
        return result;
    }
    static std::uint32_t seed(const AcustraEngine& e,int string) {return e.voices_[std::size_t(string)].randomState;}
    static void geometry(AcustraEngine& e,PickingTechnique tool,double target,std::ostream& out) {
        // Source-only rest-shape reference, never advanced through audio.
        // A unit frame (integer period=written line length) makes the delay
        // history a complete periodic spatial profile; it is not a full
        // dispersive-waveguide modal decomposition. Pick velocity share is
        // zeroed here only, equally for control and candidate.
        constexpr int string=0,length=500;
        auto& voice=e.voices_[string];voice.velocity=1.0f;voice.fret=0;
        voice.harmonic=1;voice.midiChannel=2;voice.mpeMember=true;
        for(auto& loop:voice.loops) loop.currentDelay=loop.targetDelay=float(length);
        voice.contactPeriodSamples=float(length);
        const auto saved=voice.randomState;const float offset=.02f*e.nextNoise(voice);voice.randomState=saved;
        e.mpeTimbre_[1]=float((target-.05-offset)/.41);
        e.initialisePluck(voice,string,1.0f);
        if(std::abs(voice.pluckPoint-target)>1e-6) throw std::runtime_error("fixed source point was not reached");
        out<<"{\"picking\":"<<int(tool)<<",\"target\":"<<target<<",\"point\":"<<voice.pluckPoint
           <<",\"integer_period\":"<<length<<",\"planes\":[";
        for(int plane=0;plane<2;++plane) {
            const auto& loop=voice.loops[std::size_t(plane)];std::array<double,12> magnitudes{};
            for(int h=1;h<=12;++h) {
                std::complex<double> sum{};
                for(int k=0;k<length;++k) {
                    const int index=(loop.writeIndex-k-1+AcustraEngine::maximumDelaySamples)%AcustraEngine::maximumDelaySamples;
                    const double y=loop.delay[std::size_t(index)];
                    if(!std::isfinite(y))throw std::runtime_error("nonfinite source history");
                    sum+=y*std::polar(1.0,-2*std::numbers::pi*h*k/length);
                }
                magnitudes[std::size_t(h-1)]=std::abs(sum)/length;
            }
            const int nullH=std::abs(target-.2)<1e-6?5:4;
            const double ratio=magnitudes[std::size_t(nullH-1)]/magnitudes[0];
            const double position=voice.releaseShapePosition[std::size_t(plane)];
#if defined(ACUSTRA_ANALYSIS_COMMON_PLUCK_CENTER)
            if(std::abs(position-target)>1e-6 || !(ratio<1e-5))throw std::runtime_error("common-center source geometry/comb-null guard failed");
#else
            const double expected=target+(plane==0?-.006:.009);
            if(std::abs(position-expected)>1e-6 || !(ratio>1e-3))throw std::runtime_error("authored offset negative-control guard failed");
#endif
            if(plane)out<<',';
            out<<"{\"plane\":"<<plane<<",\"shape_position\":"<<position<<",\"expected_common_null_harmonic\":"<<nullH
               <<",\"null_to_H1_amplitude\":"<<ratio<<",\"magnitudes\":[";
            for(int h=0;h<12;++h)out<<(h?",":"")<<magnitudes[std::size_t(h)];out<<"]}";
        }
        out<<"]}";
    }
};
}
namespace {
using A=acustra::AcustraEngineTestAccess;
acustra::EngineParameters parameters(int model,acustra::PickingTechnique tool) {
    acustra::EngineParameters p;p.picking=tool;p.room=0;
    if(model) {p.guitarModel=acustra::GuitarModel::Bellido1978;p.shape=acustra::BodyShape::Auditorium;p.bodyMaterial=acustra::BodyMaterial::Mahogany;}
    return p;
}
auto prepared(int model,int rate,acustra::PickingTechnique tool) {
    // Match the previously retained Finger96 native fixture's setup order.
    auto e=std::make_unique<acustra::AcustraEngine>();e->prepare(rate,256);e->setParameters(parameters(model,tool));e->setStringPerChannelMode(true);
    std::array<float,256> l{},r{};for(int i=0;i<40;++i)e->process(l.data(),r.data(),256);return e;
}
void source(const std::filesystem::path& out) {
    std::ofstream report(out/"source-geometry.json");report<<std::setprecision(12)<<"{\"source_only\":true,\"unit_frame\":true,\"rest_pick_velocity_share\":0,\"cases\":[";
    bool first=true;
    for(auto tool:{acustra::PickingTechnique::Finger,acustra::PickingTechnique::Pick,acustra::PickingTechnique::Thumb})for(double p:{.2,.25}) {
        auto e=prepared(0,48000,tool);auto calibration=acustra::fittedPhysicalCalibration;calibration.pickReleaseVelocityShare=0;
        e->setPhysicalCalibration(calibration);
        if(!first)report<<',';first=false;A::geometry(*e,tool,p,report);
    }
    report<<"]}\n";if(!report)throw std::runtime_error("source report write failed");
}
void captures(const std::filesystem::path& out) {
    constexpr std::array<std::array<int,2>,8> notes{{{40,1},{45,2},{51,3},{57,4},{60,5},{66,6},{72,6},{78,6}}};
    std::ofstream manifest(out/"manifest.json");manifest<<std::setprecision(17)<<"{\"schema\":1,\"controls\":{\"room\":0,\"settling_blocks\":40,\"block\":256,\"duration\":1.4,\"string_per_channel\":true},\"coefficient_sets\":[";
    bool first=true;
    for(int model=0;model<2;++model)for(int rate:{44100,48000,96000}) {
        auto e=prepared(model,rate,acustra::PickingTechnique::Finger);
        if(!first)manifest<<',';first=false;
        manifest<<"{\"model\":"<<model<<",\"rate\":"<<rate<<",\"six_ports\":"<<(A::ports(*e)?"true":"false")<<",\"coefficients\":[";
        const auto c=A::coefficients(*e);for(std::size_t i=0;i<c.size();++i)manifest<<(i?",":"")<<c[i];manifest<<"]}";
    }
    manifest<<"],\"examples\":[";first=true;int count=0;
    for(int model=0;model<2;++model)for(int rate:{44100,48000,96000})for(auto tool:{acustra::PickingTechnique::Finger,acustra::PickingTechnique::Pick,acustra::PickingTechnique::Thumb})for(auto note:notes)for(int velocity:{16,112}) {
        auto e=prepared(model,rate,tool),twin=prepared(model,rate,tool);
        const auto c=A::coefficients(*e);const auto initialSeed=A::seed(*e,note[1]-1);
        e->noteOn(note[0],float(velocity)/127,note[1]);twin->noteOn(note[0],float(velocity)/127,note[1]);
        const auto releaseSeed=A::seed(*e,note[1]-1);
        const std::string modelName=model?"bellido1978":"original",toolName=tool==acustra::PickingTechnique::Finger?"finger":tool==acustra::PickingTechnique::Pick?"pick":"thumb";
        const auto key=modelName+"-r"+std::to_string(rate)+"-"+toolName+"-m"+std::to_string(note[0])+"-v"+std::to_string(velocity);
        std::ofstream audio(out/(key+".f32"),std::ios::binary);std::array<float,256> l{},r{},tl{},tr{};double maximum=0;
        const int frames=int(1.4*rate);
        for(int offset=0;offset<frames;offset+=256) {
            const int n=std::min(256,frames-offset);e->process(l.data(),r.data(),n);twin->process(tl.data(),tr.data(),n);
            // The observed instance is read between blocks; the twin is not.
            if(!A::ports(*e))throw std::runtime_error("lost reciprocal string port");
            (void)A::seed(*e,note[1]-1);
            for(int i=0;i<n;++i) {
                if(!std::isfinite(l[i])||!std::isfinite(r[i])||!std::isfinite(tl[i])||!std::isfinite(tr[i]))throw std::runtime_error("nonfinite native output");
                if(std::bit_cast<std::uint32_t>(l[i])!=std::bit_cast<std::uint32_t>(tl[i])||std::bit_cast<std::uint32_t>(r[i])!=std::bit_cast<std::uint32_t>(tr[i]))throw std::runtime_error("observer changed audio");
                maximum=std::max({maximum,std::abs(double(l[i])),std::abs(double(r[i]))});
                audio.write(reinterpret_cast<const char*>(&l[i]),sizeof(float));audio.write(reinterpret_cast<const char*>(&r[i]),sizeof(float));
            }
        }
        if(c!=A::coefficients(*e))throw std::runtime_error("body/bridge coefficients changed during held-note probe");
        if(!audio)throw std::runtime_error("native audio write failed");
        if(!first)manifest<<',';first=false;++count;
        manifest<<"{\"id\":\""<<key<<"\",\"path\":\""<<key<<".f32\",\"model\":\""<<modelName<<"\",\"picking\":\""<<toolName<<"\",\"midi\":"<<note[0]<<",\"velocity\":"<<velocity<<",\"string_channel\":"<<note[1]<<",\"sample_rate\":"<<rate<<",\"channels\":2,\"initial_seed\":"<<initialSeed<<",\"release_seed\":"<<releaseSeed<<",\"final_seed\":"<<A::seed(*e,note[1]-1)<<",\"maximum_audio\":"<<maximum<<",\"observer_bit_parity\":true,\"finite\":true,\"six_ports\":true,\"modal_coefficients_unchanged\":true}";
    }
    manifest<<"]}\n";if(!manifest)throw std::runtime_error("manifest write failed");std::cout<<count<<" native captures, finite audio / observer parity / six ports / invariant stable modal coefficients\n";
}
}
int main(int argc,char**argv) {
    try {
        if(argc!=3)throw std::runtime_error("usage: CenterProbe source|native NEW_OUTPUT_DIRECTORY");
        const std::filesystem::path out(argv[2]);if(std::filesystem::exists(out))throw std::runtime_error("refusing existing output directory");std::filesystem::create_directories(out);
        if(std::string(argv[1])=="source")source(out);else if(std::string(argv[1])=="native")captures(out);else throw std::runtime_error("invalid phase");return 0;
    }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
}

build-realism/common-pluck-center/run.py.source:
#!/usr/bin/env python3
"""Bounded frozen native common-pluck-center screen, diagnostic only."""
import argparse, hashlib, json, os, subprocess, sys, time
from pathlib import Path
HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
BASE = ROOT / 'build-realism/cross-model-baseline'
FROZEN = HERE / 'frozen'
FLAGS = ['-std=c++20','-O3','-DNDEBUG','-arch','arm64','-mmacosx-version-min=11.0','-fPIC','-Wall','-Wextra','-Wpedantic']
ENV = {**os.environ, 'OPENBLAS_NUM_THREADS':'1', 'OMP_NUM_THREADS':'1'}
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def save(p,d): Path(p).write_text(json.dumps(d,indent=2,allow_nan=False)+'\n')
def command(args,log):
    record = {'argv':[str(x) for x in args], 'log':str(log), 'started_unix':time.time()}
    with (HERE/'commands.jsonl').open('a') as ledger: ledger.write(json.dumps(record)+'\n')
    print('running',Path(log).name,flush=True)
    with Path(log).open('x') as f:
        r=subprocess.run(record['argv'],stdout=f,stderr=subprocess.STDOUT,env=ENV,cwd=ROOT)
    record.update(returncode=r.returncode,seconds=time.time()-record['started_unix'],log_sha256=sha(log))
    with (HERE/'commands.jsonl').open('a') as ledger: ledger.write(json.dumps(record)+'\n')
    if r.returncode: raise RuntimeError(f'command failed: {log}')
    return record
def parity(a,b):
    aa={p.name:p for p in Path(a).glob('model-*.f32')};bb={p.name:p for p in Path(b).glob('model-*.f32')}
    assert aa.keys()==bb.keys(), 'baseline file sets differ'
    records=[{'file':n,'frozen_sha256':sha(aa[n]),'cached_sha256':sha(bb[n])} for n in sorted(aa)]
    for row in records: row['equal']=row['frozen_sha256']==row['cached_sha256']
    return {'count':len(records),'all_bit_identical':all(x['equal'] for x in records),'files':records}
def build():
    expected=json.loads((HERE/'frozen-provenance.json').read_text())['files']
    assert all(sha(FROZEN/n)==v for n,v in expected.items()),'frozen source changed'
    records=[]
    for condition in ('baseline','common'):
        dest=HERE/condition;dest.mkdir(exist_ok=False)
        defines=[] if condition=='baseline' else ['-DACUSTRA_ANALYSIS_COMMON_PLUCK_CENTER=1']
        records.append(command(['c++',*FLAGS,*defines,'-I',FROZEN/'Source','-c',FROZEN/'Source/DSP/AcustraEngine.cpp','-o',dest/'AcustraEngine.o'],dest/'engine-build.log'))
        for name in ('PhysicalFitRenderer','ExternalCorpusRenderer'):
            args=['c++',*FLAGS,*defines,'-I',FROZEN/'Source',FROZEN/'Tools'/f'{name}.cpp',dest/'AcustraEngine.o']
            if name=='PhysicalFitRenderer': args.append(HERE/'libAcustraReferenceBank.a')
            records.append(command([*args,'-o',dest/f'Acustra{name}'],dest/f'{name}-build.log'))
    save(HERE/'builds.json',{'flags':FLAGS,'commands':records,'binaries':{str(p.relative_to(HERE)):sha(p) for c in ('baseline','common') for p in (HERE/c).glob('Acustra*') if p.suffix!='.o'}})
def corpus():
    provenance=json.loads((BASE/'provenance.json').read_text()); records=[];proofs=[]
    for condition in ('baseline','common'):
        if condition=='common':
            baseline=json.loads((HERE/'baseline-parity.json').read_text())
            assert baseline['count']==246 and baseline['all_bit_identical'],'all frozen baseline audio must pass before candidate scores'
        dest=HERE/condition
        for model in ('original','bellido1978'):
            run=provenance['runs'][model]
            bank=dest/f'bank-{model}';external=dest/f'external-{model}'
            cmd=run['bank_render']['command'].copy();cmd[0]=str(dest/'AcustraPhysicalFitRenderer')
            old=str(BASE/f'bank-{model}');assert old in cmd;cmd[cmd.index(old)]=str(bank)
            records.append(command(cmd,dest/f'{model}-bank-render.log'))
            for split in ('train','validation','flattop'):
                records.append(command([sys.executable,FROZEN/'Tools/FitPhysicalModel.py',bank/f'{split}.json'],bank/f'{split}-score.json'))
            cmd=run['external']['command'].copy();cmd[0]=sys.executable;cmd[1]=str(FROZEN/'Tools/BenchmarkOpenCorpora.py')
            cmd[cmd.index('--renderer')+1]=str(dest/'AcustraExternalCorpusRenderer')
            cmd[cmd.index('--output')+1]=str(external);cmd[cmd.index('--jobs')+1]='1'
            records.append(command(cmd,dest/f'{model}-external.log'))
            if condition=='baseline':
                for kind in ('bank','external'):
                    proofs.append({'model':model,'kind':kind,**parity(dest/f'{kind}-{model}',BASE/f'{kind}-{model}')})
        if condition=='baseline':
            proof={'count':sum(x['count'] for x in proofs),'all_bit_identical':all(x['all_bit_identical'] for x in proofs),'proofs':proofs}
            save(HERE/'baseline-parity.json',proof)
            assert proof['count']==246 and proof['all_bit_identical'], 'baseline audio mismatch'
            print('All 246 frozen baseline files match cached audio exactly.',flush=True)
    comparisons=[]
    for model in ('original','bellido1978'):
        for kind in ('bank','external'):
            old=HERE/'baseline'/f'{kind}-{model}';new=HERE/'common'/f'{kind}-{model}'
            for p in sorted(old.glob('*-score.json')):
                b=json.loads(p.read_text());n=json.loads((new/p.name).read_text())
                assert b['example_count']==n['example_count']
                assert b['unique_model_count']==n['unique_model_count']
                counts={k:{'baseline':v['count'],'common':n['terms'][k]['count']} for k,v in b['terms'].items()}
                # Target-valid residuals remain penalized rather than dropped;
                # dynamics may otherwise vary with model eligibility. Preserve
                # and require the full term/dynamic residual coverage here.
                assert all(v['baseline']==v['common'] for v in counts.values()),'term/dynamics coverage changed'
                changes={'total':100*(n['score']/b['score']-1)}
                changes.update({k:None if v['score'] is None else 100*(v['score']/b['terms'][k]['score']-1) for k,v in n['terms'].items()})
                comparisons.append({'model':model,'kind':kind,'split':p.name.removesuffix('-score.json'),'examples':b['example_count'],'unique_models':b['unique_model_count'],'term_coverage':counts,'coverage_equal':True,'baseline_score':b['score'],'common_score':n['score'],'baseline_terms':b['terms'],'common_terms':n['terms'],'percent_change':changes,'total_body_guard_pass':changes['total']<=1 and changes['body']<=1,'baseline_score_sha256':sha(p),'common_score_sha256':sha(new/p.name)})
    report={'schema':1,'protocol_sha256':sha(HERE/'PROTOCOL.json'),'commands':records,'baseline_audio_parity':proof,'comparisons':comparisons,'all_total_body_guards_pass':all(r['total_body_guard_pass'] for r in comparisons),'promotion':'None; native/source gates and fresh blind listening still required; current recordings have no measured contact-position labels.'}
    save(HERE/'corpus-summary.json',report)
    print(json.dumps({'all_total_body_guards_pass':report['all_total_body_guards_pass'],'comparisons':[{k:r[k] for k in ('model','kind','split','baseline_score','common_score','percent_change','total_body_guard_pass')} for r in comparisons]},indent=2),flush=True)
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('phase',choices=('build','corpus'));a=p.parse_args()
    {'build':build,'corpus':corpus}[a.phase]()

