#!/usr/bin/env python3
"""All native center outcomes; frozen descriptor/pitch definitions unchanged."""
from pathlib import Path
import hashlib,json,math,sys
import numpy as np
HERE=Path(__file__).resolve().parent
sys.path.insert(0,str(HERE/'frozen/Tools'))
import FitPhysicalModel as F
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def clean(x):
    if isinstance(x,dict):return {str(k):clean(v) for k,v in x.items()}
    if isinstance(x,(tuple,list)):return [clean(v) for v in x]
    if isinstance(x,(bool,np.bool_)):return bool(x)
    if isinstance(x,(float,np.floating)):return float(x) if math.isfinite(x) else None
    if isinstance(x,(int,np.integer)):return int(x)
    return x
def stroke_onset(x,rate):
    width=round(rate*.001);energy=x*x;prefix=np.r_[0,np.cumsum(energy)];s=np.arange(x.size)
    rms=np.sqrt(np.maximum(prefix[1:]-prefix[np.maximum(s+1-width,0)],0)/width)
    found=np.flatnonzero(rms>.1*rms.max())
    if not found.size:return 0
    onset=int(found[0])
    while onset>0 and rms[onset]>.01*rms.max():onset-=1
    return onset
def balance(x,rate,midi,onset):
    begin=onset+round(.03*rate);segment=x[begin:begin+round(.3*rate)]
    power=np.abs(np.fft.rfft(segment*np.hanning(segment.size),1<<16))**2
    frequencies=np.fft.rfftfreq(1<<16,1/rate);f0=440*2**((midi-69)/12);peaks=[]
    for h in range(1,13):
        f=h*f0;selected=(frequencies>=f*.975)&(frequencies<=f*1.025+2)
        peaks.append(float(power[selected].max()) if np.any(selected) else 0)
    return 10*np.log10(max(sum(peaks[4:]),1e-30)/max(sum(peaks[:4]),1e-30))
def measure(condition):
    directory=HERE/condition/'native-probe';manifest=json.loads((directory/'manifest.json').read_text());rows={}
    for index,e in enumerate(manifest['examples']):
        rate,x=F._read_audio(e,directory,None,None);stereo=np.fromfile(directory/e['path'],dtype='<f4').reshape(-1,2)
        assert np.isfinite(stereo).all();nz=np.flatnonzero(np.any(stereo!=0,axis=1))
        stroke=stroke_onset(x,rate);onset=F._onset(x,rate)
        _,tuning,settled,sl=F._harmonic_features(x,rate,onset,e['midi'])
        early=F._pitch_trajectory_features(x,rate,onset,settled,sl)
        rows[e['id']]={**e,'sha256':sha(directory/e['path']),'first_nonzero_sample':int(nz[0]) if nz.size else None,
            'fit_onset_sample':onset,'stroke_onset_sample':stroke,'velocity_balance_db':balance(x,rate,e['midi'],stroke),
            'settled_pitch_cents_median_H1_H4':np.nanmedian(tuning[:4]),'H1_pitch_cents':tuning[0],'early_relative_pitch_cents':early.tolist()}
        if index%48==0:print(condition,index,'/',len(manifest['examples']),flush=True)
    return manifest,rows
def main():
    destination=HERE/'native-summary.json'
    if destination.exists():raise RuntimeError('refusing existing native summary')
    baseline,b=measure('baseline');candidate,c=measure('common');assert b.keys()==c.keys() and len(b)==288
    modal_equal=baseline['coefficient_sets']==candidate['coefficient_sets'];assert modal_equal
    historical=HERE.parent/'finger-width-screen/multiplier-1.0/native-probe'
    historical_proof=[]
    if historical.exists():
        for r in b.values():
            if r['picking']!='finger':continue
            old_id=r['id'].replace('-finger-','-');p=historical/(old_id+'.f32')
            historical_proof.append({'id':r['id'],'old_path':str(p),'equal':p.is_file() and sha(p)==r['sha256']})
        assert len(historical_proof)==96 and all(r['equal'] for r in historical_proof),'historical baseline Finger96 native parity failed'
    comparisons=[]
    for key,r in c.items():
        old=b[key];pitch=r['settled_pitch_cents_median_H1_H4']-old['settled_pitch_cents_median_H1_H4']
        early=np.asarray(r['early_relative_pitch_cents'])-old['early_relative_pitch_cents']
        first=r['first_nonzero_sample']==old['first_nonzero_sample'];onset=1000*(r['fit_onset_sample']-old['fit_onset_sample'])/r['sample_rate']
        seeds=all(r[k]==old[k] for k in ('initial_seed','release_seed','final_seed'))
        comparisons.append({'id':key,'first_nonzero_unchanged':first,'fit_onset_delta_ms':onset,'settled_pitch_delta_cents':pitch,
            'early_pitch_delta_cents':early.tolist(),'same_rng_draws':seeds,'onset_gate':first and abs(onset)<=1,
            'pitch_gate':bool(np.isfinite(pitch) and abs(pitch)<=3 and np.isfinite(early).all() and len(early)==3 and np.max(np.abs(early))<=3)})
    velocity=[]
    for condition,rows in (('baseline',b),('common',c)):
        for model in ('original','bellido1978'):
            for rate in (44100,48000,96000):
                for tool in ('finger','pick','thumb'):
                    rises=[]
                    for midi in (40,45,51,57,60,66,72,78):
                        values={r['velocity']:r for r in rows.values() if r['model']==model and r['sample_rate']==rate and r['picking']==tool and r['midi']==midi}
                        rises.append(values[112]['velocity_balance_db']-values[16]['velocity_balance_db'])
                    median=np.median(rises)
                    velocity.append({'condition':condition,'model':model,'sample_rate':rate,'picking':tool,'median_rise_db':median,'per_note_rise_db':rises,
                        'historical8_to10_aspiration':bool(8<=median<=10) if tool=='finger' else None})
    report={'schema':1,'protocol_sha256':sha(HERE/'PROTOCOL.json'),'analyzer_sha256':sha(__file__),
        'definition':{'pitch':'Frozen FitPhysicalModel settled median H1-H4 and three early relative-pitch points; all deltas <=3 cents',
            'onset':'Exact first nonzero stereo sample unchanged plus own-signal FitPhysicalModel onset delta <=1ms',
            'brightness':'Historical 65536-point Hann peak-power estimator,30-330ms after trailing1ms stroke onset,H5-H12/H1-H4; picked-reference8-10dB is an aspiration, not this source-geometry eligibility',
            'coefficient_snapshot':'Actual active heave+rock denominators/numerators, active indices/rocking flags, all3 bridge residues/immediate coefficients; body count/ordering/all10 pole+residue coefficients. All poles stable and six reciprocal ports observed before and throughout captures.'},
        'rows':{'baseline':list(b.values()),'common':list(c.values())},'comparisons':comparisons,'velocity_cells':velocity,
        'actual_modal_coefficients_bit_equal':modal_equal,'baseline_Finger96_historical_audio_parity':historical_proof,
        'gates':{'onset':all(x['onset_gate'] for x in comparisons),'pitch':all(x['pitch_gate'] for x in comparisons),
            'rng_draws':all(x['same_rng_draws'] for x in comparisons),'finite_observer_ports_modal_stability':all(r[k] for rows in (b,c) for r in rows.values() for k in ('finite','observer_bit_parity','six_ports','modal_coefficients_unchanged'))}}
    destination.write_text(json.dumps(clean(report),indent=2,allow_nan=False)+'\n')
    print('native gates',report['gates'],flush=True)
if __name__=='__main__':main()

