import hashlib, json, math, pathlib, sys
record = json.loads(pathlib.Path(sys.argv[1]).read_text())
def sha(b): return hashlib.sha256(b).hexdigest()
def canonical(d): return json.dumps(d, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()
for item in record["report_inputs"].values():
    assert sha(canonical(item["data"])) == item["canonical_data_sha256"]
    p = pathlib.Path(item["path_at_measurement"])
    if p.exists():
        assert sha(p.read_bytes()) == item["sha256"], str(p)
        assert json.loads(p.read_text()) == item["data"], str(p)
for item in record["laboratory_tools"].values():
    assert sha(item["source"].encode()) == item["sha256"]
for item in record["offline_hooks"].values():
    assert sha(item["patch"].encode()) == item["sha256"]
for item in record["baseline_references"].values():
    p = pathlib.Path(item["path_at_measurement"])
    if p.exists(): assert sha(p.read_bytes()) == item["sha256"], str(p)
ids = record["candidate_score_report_ids"]
assert len(ids) == 24
for key in ids:
    r = record["report_inputs"][key]["data"]
    assert len(r["weighted_residuals"]) == sum(t["count"] for t in r["terms"].values())
    assert all(math.isfinite(v) for v in r["weighted_residuals"])
assert record["decisions"]["finger_seed_ensemble"]["production_candidate"] is False
assert record["decisions"]["finger_burst_direction"]["protocol_v1_pass"] is False
assert record["decisions"]["finger_burst_direction"]["protocol_v2_pass"] is False
assert record["decisions"]["common_pluck_center"]["full_eligibility"] is False
assert len(record["decisions"]["finger_burst_direction"]["failed_corpus_comparisons"]) == 3
assert len(record["decisions"]["common_pluck_center"]["failed_corpus_comparisons"]) == 7
print(json.dumps({"embedded_reports_validated": len(record["report_inputs"]), "laboratory_sources_validated": len(record["laboratory_tools"]), "hooks_validated": len(record["offline_hooks"]), "candidate_score_reports": len(ids), "all_checks_pass": True}))
